import unittest

from slug import slugify


class SlugifyTests(unittest.TestCase):
    def test_ascii_letters_and_digits(self):
        self.assertEqual(slugify("Hello WORLD 123"), "hello-world-123")

    def test_separator_runs_and_edges(self):
        self.assertEqual(slugify(" -- Hello__\t\nWorld!! "), "hello-world")

    def test_empty_and_separator_only(self):
        for text in ("", "---", " \t\n", "é中文🙂"):
            with self.subTest(text=text):
                self.assertEqual(slugify(text), "")

    def test_non_ascii_separates_even_when_case_maps_to_ascii(self):
        self.assertEqual(slugify("AKBİCéD中文E🙂F"), "a-b-c-d-e-f")

    def test_existing_hyphens(self):
        self.assertEqual(slugify("Already-a--SLUG"), "already-a-slug")

    def test_every_ascii_character(self):
        for codepoint in range(128):
            character = chr(codepoint)
            expected = character.lower() if character.isalnum() else ""
            with self.subTest(codepoint=codepoint):
                self.assertEqual(slugify(character), expected)

    def test_input_is_unchanged(self):
        text = " Hello__WORLD! "
        slugify(text)
        self.assertEqual(text, " Hello__WORLD! ")


if __name__ == "__main__":
    unittest.main()
